using System.Text;
using CombatV051.Domain;
using Newtonsoft.Json;
using Newtonsoft.Json.Serialization;

internal static class JsonWriterGenerator
{
    static string Name(Type t)=>t.IsArray?Name(t.GetElementType())+"[]":t.IsGenericType?t.GetGenericTypeDefinition().FullName.Split('`')[0]+"<"+string.Join(",",t.GetGenericArguments().Select(Name))+">":t.FullName.Replace('+','.');
    static bool Scalar(Type t)=>new[]{typeof(string),typeof(bool),typeof(byte),typeof(sbyte),typeof(short),typeof(ushort),typeof(int),typeof(uint),typeof(long),typeof(ulong),typeof(float),typeof(double),typeof(decimal),typeof(char)}.Contains(t);
    static readonly IContractResolver Resolver=new DefaultContractResolver();
    static bool DefaultHandlingSupported(JsonProperty p)
    {
        if(!p.DefaultValueHandling.HasValue)return true;
        // Emit only CLR-default omission with no explicit DefaultValue attribute.
        // Numeric/enum zero extensions preserve legacy bytes; custom structs,
        // explicit defaults and Required combinations retain the original fallback.
        return p.DefaultValueHandling==DefaultValueHandling.Ignore&&p.DefaultValue==null&&p.Required==Required.Default&&
            (!p.PropertyType.IsValueType||Scalar(p.PropertyType)||p.PropertyType.IsEnum);
    }
    static bool Supported(JsonObjectContract c)
    {
        if(c==null||c.Converter!=null||c.InternalConverter!=null||c.IsReference.HasValue||c.OnSerializingCallbacks.Count!=0||c.OnSerializedCallbacks.Count!=0||c.OnErrorCallbacks.Count!=0||c.ExtensionDataGetter!=null||c.ItemRequired.HasValue||c.ItemNullValueHandling.HasValue||c.ItemConverter!=null||c.ItemIsReference.HasValue||c.ItemReferenceLoopHandling.HasValue||c.ItemTypeNameHandling.HasValue)return false;
        return c.Properties.Where(p=>p.Readable&&!p.Ignored).All(p=>p.Converter==null&&p.ItemConverter==null&&p.ShouldSerialize==null&&p.GetIsSpecified==null&&DefaultHandlingSupported(p)&&!p.NullValueHandling.HasValue&&!p.ReferenceLoopHandling.HasValue&&!p.TypeNameHandling.HasValue&&!p.IsReference.HasValue&&!p.ItemIsReference.HasValue&&!p.ItemReferenceLoopHandling.HasValue&&!p.ItemTypeNameHandling.HasValue);
    }
    static string Signature(Type type)
    {
        var c=Resolver.ResolveContract(type) as JsonObjectContract;
        if(c==null)return "unsupported:"+Resolver.ResolveContract(type).GetType().FullName;
        return JsonConvert.SerializeObject(new{kind=c.GetType().FullName,converter=c.Converter?.GetType().FullName,internalConverter=c.InternalConverter?.GetType().FullName,c.IsReference,c.MemberSerialization,onSerializing=c.OnSerializingCallbacks.Count,onSerialized=c.OnSerializedCallbacks.Count,onError=c.OnErrorCallbacks.Count,extension=c.ExtensionDataGetter!=null,c.ItemRequired,c.ItemNullValueHandling,itemConverter=c.ItemConverter?.GetType().FullName,c.ItemIsReference,c.ItemReferenceLoopHandling,c.ItemTypeNameHandling,properties=c.Properties.Select(p=>new{p.PropertyName,p.UnderlyingName,type=Name(p.PropertyType),p.Ignored,p.Readable,p.Writable,p.Order,p.Required,p.NullValueHandling,p.DefaultValueHandling,p.DefaultValue,p.ReferenceLoopHandling,p.TypeNameHandling,p.IsReference,p.ItemIsReference,p.ItemReferenceLoopHandling,p.ItemTypeNameHandling,converter=p.Converter?.GetType().FullName,itemConverter=p.ItemConverter?.GetType().FullName,shouldSerialize=p.ShouldSerialize!=null,isSpecified=p.GetIsSpecified!=null}).ToArray()},Formatting.None);
    }
    internal static void Generate(string output)
    {
        var types=typeof(CombatState).Assembly.GetTypes().Where(t=>t.Namespace=="CombatV051.Domain"&&t.IsPublic&&t.IsClass&&t.IsDefined(typeof(SerializableAttribute),false)).OrderBy(t=>t.Name,StringComparer.Ordinal).ToArray();
        var containers=new HashSet<Type>();
        void Visit(Type t){if(t.IsArray||t.IsGenericType){if(!containers.Add(t))return;if(t.IsArray)Visit(t.GetElementType());else foreach(var a in t.GetGenericArguments())Visit(a);}}
        foreach(var t in types)if(Resolver.ResolveContract(t) is JsonObjectContract c)foreach(var p in c.Properties.Where(p=>p.Readable&&!p.Ignored))Visit(p.PropertyType);
        var all=types.Concat(containers.OrderBy(Name,StringComparer.Ordinal)).ToArray();
        var b=new StringBuilder("// Generated by Tools/P47StoreBench: generate-json. Do not hand-edit contracts.\n// Exact current Newtonsoft contracts only; unsupported settings/values use the original codec.\nusing System;\nusing System.IO;\nusing System.Globalization;\nusing Newtonsoft.Json;\nnamespace CombatV051.Domain\n{\npublic static class CombatTypedJson\n{\n");
        b.AppendLine("    sealed class FallbackRequiredException:Exception {}\n    static bool Compatible(JsonSerializerSettings s)\n    {\n        return s!=null && JsonConvert.DefaultSettings==null && s.ContractResolver==null && s.Converters.Count==0 && s.SerializationBinder==null && s.ReferenceResolverProvider==null && s.TraceWriter==null && s.Error==null && s.EqualityComparer==null\n            && s.TypeNameHandling==TypeNameHandling.None && s.NullValueHandling==NullValueHandling.Include && s.DefaultValueHandling==DefaultValueHandling.Include && s.PreserveReferencesHandling==PreserveReferencesHandling.None && s.ReferenceLoopHandling==ReferenceLoopHandling.Error\n            && s.FloatFormatHandling==FloatFormatHandling.String && s.StringEscapeHandling==StringEscapeHandling.Default && s.DateFormatHandling==DateFormatHandling.IsoDateFormat && s.DateTimeZoneHandling==DateTimeZoneHandling.RoundtripKind && ReferenceEquals(s.Culture,CultureInfo.InvariantCulture);\n    }");
        b.AppendLine("    public static bool TryWrite(object value,JsonSerializerSettings settings,out string result)\n    {\n        result=null;if(!Compatible(settings))return false;\n        if(value==null){result=\"null\";return true;}\n        Type type=value.GetType();\n        try\n        {\n            using(var text=new StringWriter(CultureInfo.InvariantCulture))\n            using(var w=new JsonTextWriter(text))\n            {\n                w.Formatting=Formatting.None;");
        for(int i=0;i<all.Length;i++)b.AppendLine("                "+(i==0?"if":"else if")+"(type==typeof("+Name(all[i])+"))Write(w,("+Name(all[i])+")value);");
        b.AppendLine("                else return false;\n                w.Flush();result=text.ToString();return true;\n            }\n        }\n        catch(FallbackRequiredException){return false;}\n    }");
        b.AppendLine("    public static string ContractSignature(Type type)\n    {");
        foreach(var t in types)b.AppendLine("        if(type==typeof("+Name(t)+"))return "+JsonConvert.SerializeObject(Signature(t))+";");
        b.AppendLine("        return null;\n    }");
        string Emit(Type t,string value)
        {
            if(t.IsEnum)return "w.WriteValue(("+Name(Enum.GetUnderlyingType(t))+")"+value+");";
            if(Scalar(t))return "w.WriteValue("+value+");";
            return all.Contains(t)?"Write(w,"+value+");":"throw new FallbackRequiredException();";
        }
        foreach(var t in types)
        {
            b.AppendLine("    static void Write(JsonTextWriter w,"+Name(t)+" v)\n    {\n        if(v==null){w.WriteNull();return;}");
            var c=Resolver.ResolveContract(t) as JsonObjectContract;
            if(!Supported(c)){b.AppendLine("        throw new FallbackRequiredException();\n    }");continue;}
            if(!t.IsSealed)b.AppendLine("        if(v.GetType()!=typeof("+Name(t)+"))throw new FallbackRequiredException();");
            b.AppendLine("        w.WriteStartObject();");
            foreach(var p in c.Properties.Where(p=>p.Readable&&!p.Ignored))
            {
                if((p.Required==Required.Always||p.Required==Required.DisallowNull)&&(!p.PropertyType.IsValueType||Nullable.GetUnderlyingType(p.PropertyType)!=null))b.AppendLine("        if(v."+p.UnderlyingName+"==null)throw new FallbackRequiredException();");
                bool omitDefault=p.DefaultValueHandling==DefaultValueHandling.Ignore;
                string condition=p.PropertyType.IsValueType?
                    "!System.Collections.Generic.EqualityComparer<"+Name(p.PropertyType)+">.Default.Equals(v."+p.UnderlyingName+",default("+Name(p.PropertyType)+"))":
                    "v."+p.UnderlyingName+"!=null";
                b.AppendLine("        "+(omitDefault?"if("+condition+"){":"")+"w.WritePropertyName("+JsonConvert.SerializeObject(p.PropertyName)+");"+Emit(p.PropertyType,"v."+p.UnderlyingName)+(omitDefault?"}":""));
            }
            b.AppendLine("        w.WriteEndObject();\n    }");
        }
        foreach(var t in containers.OrderBy(Name,StringComparer.Ordinal))
        {
            b.AppendLine("    static void Write(JsonTextWriter w,"+Name(t)+" v)\n    {\n        if(v==null){w.WriteNull();return;}\n        if(v.GetType()!=typeof("+Name(t)+"))throw new FallbackRequiredException();");
            var cc=Resolver.ResolveContract(t) as JsonContainerContract;
            if(cc==null||cc.Converter!=null||cc.InternalConverter!=null||cc.IsReference.HasValue||cc.OnSerializingCallbacks.Count!=0||cc.OnSerializedCallbacks.Count!=0||cc.OnErrorCallbacks.Count!=0||cc.ItemConverter!=null||cc.ItemIsReference.HasValue||cc.ItemReferenceLoopHandling.HasValue||cc.ItemTypeNameHandling.HasValue){b.AppendLine("        throw new FallbackRequiredException();\n    }");continue;}
            if(t.IsGenericType&&t.GetGenericTypeDefinition()==typeof(Dictionary<,>)&&t.GetGenericArguments()[0]==typeof(string))b.AppendLine("        w.WriteStartObject();foreach(var pair in v){w.WritePropertyName(pair.Key);"+Emit(t.GetGenericArguments()[1],"pair.Value")+"}w.WriteEndObject();");
            else if(t.IsArray||t.IsGenericType&&t.GetGenericTypeDefinition()==typeof(List<>))b.AppendLine("        w.WriteStartArray();foreach(var item in v){"+Emit(t.IsArray?t.GetElementType():t.GetGenericArguments()[0],"item")+"}w.WriteEndArray();");
            else b.AppendLine("        throw new FallbackRequiredException();");
            b.AppendLine("    }");
        }
        b.AppendLine("}\n}");File.WriteAllText(output,b.ToString());Console.WriteLine("Generated JSON writer: "+types.Length+" DTO / "+containers.Count+" containers.");
    }
}
